def get_price_by_field(field_name):
    return price_dict.get(field_name.lower(), "❌ Field not found in the data.")

# UI
st.title("📊 Data Extraction Pricing Tool")

response = st.radio("Are you pulling historical data?", ["Yes", "No"])

if response == "Yes":
    usage = st.selectbox(
        "Have you used this formula today, this month, or is it a new extraction?",
        ["Today", "Month", "New"]
    )
    
    if usage == "Month":
        st.success("💰 Price: $0.754")
    elif usage == "Today":
        st.success("💰 Price: $0.0143")
    elif usage == "New":
        st.success("💰 Price: $4.563")
else:
    field_name = st.text_input("Please enter the name of the field you want to extract:")
    if field_name:
        price = get_price_by_field(field_name)
        st.success(f"💰 Price for '{field_name}': {price}")

